 2	twostate predicate Preserved(a: array<int>, left: nat, right: nat)
 3	    reads a
 4	    requires left <= right <= a.Length
 5	{
 6	    multiset(a[left..right]) == multiset(old(a[left..right]))
 7	}
 8	
 9	ghost predicate Ordered(a: array<int>, left: nat, right: nat)
10	    reads a
11	{
12	    forall i: nat :: 0 < left <= i < right ==> a[i-1] <= a[i]
13	}
14	
15	twostate predicate Sorted(a: array<int>)
16	    reads a
17	{
18	    Ordered(a,0,a.Length) && Preserved(a,0,a.Length)
19	}
20	
21	method SelectionnSort(a: array<int>)
22	    modifies a
23	    ensures Sorted(a)
24	{
25	    for i := 0 to a.Length
26	      invariant Ordered(a,0,i)
27	      invariant Preserved(a,0,a.Length)
28	    {
29	      var minValue := a[i];
30	      var minPos := i;
31	      for j := i + 1 to a.Length
32	        invariant minPos < a.Length
33	        invariant a[minPos] == minValue
34	      {
35	        if a[j] < minValue {
36	          minValue := a[j];
37	          minPos := j;
38	        }
39	      }
40	      if i != minPos {
41	        a[i], a[minPos] := minValue, a[i];
42	      }
43	    }
44	}
