52	      invariant Preserved(a,0,a.Length)
53	    {
54	      ghost var minValue := a[i];
55	      for j := i + 1 to a.Length
56	        invariant a[i] == minValue
57	        invariant Preserved(a,0,a.Length)
58	      {
59	        label L:
60	        // assert a[..] == a[0..a.Length];
61	        assert a[..] == old@L(a[..]);
62	
63	        if a[j] < minValue {
64	          minValue := a[j];
65	        }
66	        if a[j] < a[i] {
67	            assert j != i;
68	            a[i], a[j] := a[j], a[i];
69	            // assert Preserved(a, 0, a.Length);
70	        }else{
71	            // assert Preserved(a, 0, a.Length);
72	        }
73	      }
74	      assert a[i] == minValue;
75	    }
